CREATE TABLE ${primehrSchema}.succession_cycle (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, code VARCHAR(80) NOT NULL, normalized_code VARCHAR(80) NOT NULL, title VARCHAR(200) NOT NULL, description VARCHAR(2000), policy_version_id VARCHAR(36) NOT NULL, policy_definition_version INT NOT NULL, policy_fingerprint VARCHAR(120) NOT NULL, charter_version_id VARCHAR(36) NOT NULL, nomination_opens_on DATE NOT NULL, nomination_closes_on DATE NOT NULL, eligibility_due_on DATE NOT NULL, status VARCHAR(20) NOT NULL, opened_by VARCHAR(100), opened_at DATETIMEOFFSET, closed_by VARCHAR(100), closed_at DATETIMEOFFSET, transition_reason VARCHAR(2000), record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at DATETIMEOFFSET NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT uk_succession_cycle_code UNIQUE(agency_id,normalized_code), CONSTRAINT fk_succ_cycle_policy FOREIGN KEY(policy_version_id) REFERENCES ${primehrSchema}.succession_governance_policy_version(id), CONSTRAINT fk_succ_cycle_charter FOREIGN KEY(charter_version_id) REFERENCES ${primehrSchema}.succession_committee_charter_version(id), CONSTRAINT ck_succ_cycle_version CHECK(policy_definition_version>=1), CONSTRAINT ck_succ_cycle_dates CHECK(nomination_closes_on>=nomination_opens_on AND eligibility_due_on>=nomination_closes_on), CONSTRAINT ck_succ_cycle_status CHECK(status IN('DRAFT','OPEN','CLOSED','CANCELLED'))
);
CREATE INDEX ix_succ_cycle_window ON ${primehrSchema}.succession_cycle(agency_id,status,nomination_opens_on,nomination_closes_on);
CREATE TABLE ${primehrSchema}.succession_continuity_risk_review (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, cycle_id VARCHAR(36) NOT NULL, designation_id VARCHAR(36) NOT NULL, target_type VARCHAR(20) NOT NULL, target_id BIGINT NOT NULL, job_position_id BIGINT NOT NULL, position_name VARCHAR(250) NOT NULL, plantilla_id BIGINT, plantilla_name VARCHAR(250), target_fingerprint VARCHAR(120) NOT NULL, risk_level VARCHAR(20) NOT NULL, risk_reason VARCHAR(4000) NOT NULL, continuity_controls VARCHAR(4000) NOT NULL, review_date DATE NOT NULL, next_review_date DATE NOT NULL, status VARCHAR(20) NOT NULL, finalized_by VARCHAR(100), finalized_at DATETIMEOFFSET, record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at DATETIMEOFFSET NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT uk_succession_risk_cycle_position UNIQUE(agency_id,cycle_id,designation_id), CONSTRAINT fk_succ_risk_cycle FOREIGN KEY(cycle_id) REFERENCES ${primehrSchema}.succession_cycle(id), CONSTRAINT fk_succ_risk_designation FOREIGN KEY(designation_id) REFERENCES ${primehrSchema}.succession_critical_position_designation(id), CONSTRAINT ck_succ_risk_level CHECK(risk_level IN('LOW','MODERATE','HIGH','CRITICAL')), CONSTRAINT ck_succ_risk_dates CHECK(next_review_date>=review_date), CONSTRAINT ck_succ_risk_status CHECK(status IN('DRAFT','FINALIZED'))
);
CREATE INDEX ix_succ_risk_cycle ON ${primehrSchema}.succession_continuity_risk_review(agency_id,cycle_id,status);
CREATE TABLE ${primehrSchema}.succession_candidate (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, cycle_id VARCHAR(36) NOT NULL, designation_id VARCHAR(36) NOT NULL, intake_type VARCHAR(40) NOT NULL, initiated_by VARCHAR(100) NOT NULL, employee_id BIGINT NOT NULL, employee_no VARCHAR(100) NOT NULL, employee_name VARCHAR(300) NOT NULL, appointment_id BIGINT NOT NULL, current_job_position_id BIGINT, current_plantilla_id BIGINT, employee_fingerprint VARCHAR(120) NOT NULL, target_type VARCHAR(20) NOT NULL, target_id BIGINT NOT NULL, target_job_position_id BIGINT NOT NULL, target_position_name VARCHAR(250) NOT NULL, target_plantilla_id BIGINT, target_plantilla_name VARCHAR(250), target_fingerprint VARCHAR(120) NOT NULL, nomination_reason VARCHAR(4000) NOT NULL, status VARCHAR(20) NOT NULL, notice_text VARCHAR(4000), notice_sent_by VARCHAR(100), notice_sent_at DATETIMEOFFSET, consent_statement VARCHAR(4000), consented_at DATETIMEOFFSET, submitted_by VARCHAR(100), submitted_at DATETIMEOFFSET, eligibility_outcome VARCHAR(20), eligibility_reason VARCHAR(4000), eligibility_reviewed_by VARCHAR(100), eligibility_reviewed_at DATETIMEOFFSET, withdrawn_by VARCHAR(100), withdrawn_at DATETIMEOFFSET, withdrawal_reason VARCHAR(2000), record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at DATETIMEOFFSET NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT uk_succession_candidate_cycle_target_employee UNIQUE(agency_id,cycle_id,designation_id,employee_id), CONSTRAINT fk_succ_candidate_cycle FOREIGN KEY(cycle_id) REFERENCES ${primehrSchema}.succession_cycle(id), CONSTRAINT fk_succ_candidate_designation FOREIGN KEY(designation_id) REFERENCES ${primehrSchema}.succession_critical_position_designation(id), CONSTRAINT ck_succ_candidate_type CHECK(intake_type IN('AUTHORIZED_NOMINATION','SELF_EXPRESSION_OF_INTEREST')), CONSTRAINT ck_succ_candidate_status CHECK(status IN('DRAFT','NOTICE_SENT','CONSENTED','SUBMITTED','ELIGIBLE','INELIGIBLE','WITHDRAWN')), CONSTRAINT ck_succ_candidate_eligibility CHECK(eligibility_outcome IS NULL OR eligibility_outcome IN('ELIGIBLE','INELIGIBLE'))
);
CREATE INDEX ix_succ_candidate_cycle ON ${primehrSchema}.succession_candidate(agency_id,cycle_id,status);CREATE INDEX ix_succ_candidate_employee ON ${primehrSchema}.succession_candidate(agency_id,employee_no,status);
CREATE TABLE ${primehrSchema}.succession_eligibility_finding (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, candidate_id VARCHAR(36) NOT NULL, criterion_code VARCHAR(80) NOT NULL, normalized_criterion_code VARCHAR(80) NOT NULL, criterion_label VARCHAR(200) NOT NULL, outcome VARCHAR(30) NOT NULL, reason VARCHAR(4000) NOT NULL, employee_visible BIT NOT NULL, display_order INT NOT NULL, record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at DATETIMEOFFSET NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT uk_succession_eligibility_criterion UNIQUE(agency_id,candidate_id,normalized_criterion_code), CONSTRAINT fk_succ_eligibility_candidate FOREIGN KEY(candidate_id) REFERENCES ${primehrSchema}.succession_candidate(id), CONSTRAINT ck_succ_eligibility_outcome CHECK(outcome IN('MET','NOT_MET','NEEDS_EVIDENCE')), CONSTRAINT ck_succ_eligibility_order CHECK(display_order>=1)
);
CREATE INDEX ix_succ_eligibility_candidate ON ${primehrSchema}.succession_eligibility_finding(agency_id,candidate_id,display_order);
CREATE TABLE ${primehrSchema}.succession_candidate_evidence (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, candidate_id VARCHAR(36) NOT NULL, title VARCHAR(200) NOT NULL, original_filename VARCHAR(255) NOT NULL, storage_provider VARCHAR(30) NOT NULL, storage_object_key VARCHAR(500) NOT NULL, media_type VARCHAR(120) NOT NULL, byte_size BIGINT NOT NULL, checksum VARCHAR(64) NOT NULL, visibility VARCHAR(30) NOT NULL, retention_tag VARCHAR(100) NOT NULL, uploaded_by VARCHAR(100) NOT NULL, uploaded_at DATETIMEOFFSET NOT NULL, record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at DATETIMEOFFSET NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT uk_succession_evidence_object UNIQUE(storage_object_key), CONSTRAINT fk_succ_evidence_candidate FOREIGN KEY(candidate_id) REFERENCES ${primehrSchema}.succession_candidate(id), CONSTRAINT ck_succ_evidence_size CHECK(byte_size>0), CONSTRAINT ck_succ_evidence_visibility CHECK(visibility IN('CANDIDATE_VISIBLE','COMMITTEE_RESTRICTED'))
);
CREATE INDEX ix_succ_evidence_candidate ON ${primehrSchema}.succession_candidate_evidence(agency_id,candidate_id,uploaded_at);
